sys_script_include.script:
var AppointmentUtils = Class.create();
AppointmentUtils.prototype = {
    initialize: function() {
    },

	fetchPatientAppointments: function(patientid){
		var appoint = new GlideRecord('u_appointment');
		appoint.addQuery('u_patient_id',patientid);
		appoint.query();
		return appoint;
	},


	checkAppointmentStatus: function(id){
		var _appoint = new GlideRecord('u_appointment');
		_appoint.addQuery('number', id);
		_appoint.query();
		if (_appoint.next()){
			if (_appoint.u_status== 'confirmed'){
				return "Status is Confirmed";
			}
			else{
				return "Status is not confirmed";
			}
		}
		else{
			return "No appointment found";
		}

	},

	getAppointmentDetails: function(id){
		var _appoint = new GlideRecord('u_appointment');
		_appoint.addQuery('number', id);
		_appoint.query();
		if (_appoint.next()) {
        return _appoint;
		} else {
			return null;
		}

	},

	getAppointmentDetailsByDate: function(dateStr) {
    var _date = new GlideRecord('u_appointment');
    _date.addQuery('u_appointment_date', 'CONTAINS', dateStr);
    _date.query();
    if (_date.next()) {
        return _date;
    } else {
        return null;
    }

	},

	getAppointmentDetailsByDepartment: function(department){
		var _department = new GlideRecord('u_appointment');
		_department.addQuery('u_department',department);
		_department.query();
		if (_department.next()) {
        return _department;
		} else {
			return null;
		}

	},


    type: 'AppointmentUtils'
};
